use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_symbol_usage (symbol : & str , usage_analysis : & mut HashMap < i32 , ConstantUsage >) { let mut current_num = String :: new () ; let mut is_negative = false ; let chars : Vec < char > = symbol . chars () . collect () ; for (i , & ch) in chars . iter () . enumerate () { if ch == '-' && (i == 0 || ! chars . get (i - 1) . unwrap_or (& ' ') . is_ascii_digit ()) { is_negative = true ; } else if ch . is_ascii_digit () { current_num . push (ch) ; } else { if ! current_num . is_empty () { if let Ok (num) = current_num . parse :: < i32 > () { let final_num = if is_negative { - num } else { num } ; if final_num >= - 100 && final_num <= 100 { let usage_type = determine_usage_type (symbol , final_num , i) ; let context = extract_context (symbol , i) ; let entry = usage_analysis . entry (final_num) . or_insert_with (| | ConstantUsage { value : final_num , count : 0 , usage_types : Vec :: new () , contexts : Vec :: new () , }) ; entry . count += 1 ; if ! entry . usage_types . contains (& usage_type) { entry . usage_types . push (usage_type) ; } if ! entry . contexts . contains (& context) { entry . contexts . push (context) ; } } } current_num . clear () ; is_negative = false ; } } } if ! current_num . is_empty () { if let Ok (num) = current_num . parse :: < i32 > () { let final_num = if is_negative { - num } else { num } ; if final_num >= - 100 && final_num <= 100 { let usage_type = determine_usage_type (symbol , final_num , chars . len ()) ; let context = extract_context (symbol , chars . len ()) ; let entry = usage_analysis . entry (final_num) . or_insert_with (| | ConstantUsage { value : final_num , count : 0 , usage_types : Vec :: new () , contexts : Vec :: new () , }) ; entry . count += 1 ; if ! entry . usage_types . contains (& usage_type) { entry . usage_types . push (usage_type) ; } if ! entry . contexts . contains (& context) { entry . contexts . push (context) ; } } } } }